def handle(app, svc):
    resp = svc.apply(app)
    outcome = resp.get("result", {}).get("outcome")
    credit_limit = resp.get("result", {}).get("credit_limit", 0)

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    if outcome == "approved":
        # Network rule: self_employed with requested_limit > 6000 must go to queue_review
        if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 6000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": credit_limit}

    # manual_review (or anything else) -> queue_review, never decline
    return {"action": "queue_review", "limit": 0}

